final_template:
AWSTemplateFormatVersion: '2010-09-09'

Description: >-
  IoT device-onboarding policy stack. Provisions a Lambda-backed CloudFormation
  custom resource that generates an AWS IoT Core policy scoped to each device's
  own thing name (connect, publish, subscribe, receive), and outputs the
  generated policy name. Self-contained: no external VPCs, secrets, SSM
  parameters, or cross-stack imports are referenced.

Parameters:

  PolicyNamePrefix:
    Type: String
    Default: device-onboarding
    Description: >-
      Prefix for the generated IoT policy name. Only letters, digits,
      underscores and hyphens are permitted.
    AllowedPattern: '[a-zA-Z0-9_-]+'
    ConstraintDescription: Must contain only letters, digits, underscores or hyphens.
    MinLength: 1
    MaxLength: 64

  EnvironmentTag:
    Type: String
    Default: dev
    Description: Value applied as the Environment tag on the Lambda function and IAM role.
    AllowedPattern: '[a-zA-Z0-9_-]+'
    ConstraintDescription: Must contain only letters, digits, underscores or hyphens.
    MinLength: 1
    MaxLength: 32

Resources:

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role for the IoT device-onboarding policy custom resource Lambda.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTDeviceOnboardingPolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: ManageOnboardingPolicies
                Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicyVersion
                  - iot:ListPolicyVersions
                  - iot:ListTargetsForPolicy
                Resource: !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/${PolicyNamePrefix}-*'
      Tags:
        - Key: Environment
          Value: !Ref EnvironmentTag
        - Key: ManagedBy
          Value: !Ref 'AWS::StackName'

  OnboardingPolicyFunctionLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-iot-onboarding-policy'
      RetentionInDays: 14
      Tags:
        - Key: Environment
          Value: !Ref EnvironmentTag
        - Key: ManagedBy
          Value: !Ref 'AWS::StackName'

  OnboardingPolicyFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub '${AWS::StackName}-iot-onboarding-policy'
      Description: Creates, versions and deletes the IoT device-onboarding policy for this stack.
      Handler: index.handler
      Runtime: nodejs22.x
      Role: !GetAtt LambdaExecutionRole.Arn
      Timeout: 60
      MemorySize: 256
      Environment:
        Variables:
          POLICY_NAME_PREFIX: !Ref PolicyNamePrefix
          ENVIRONMENT_TAG: !Ref EnvironmentTag
          STACK_NAME: !Ref 'AWS::StackName'
          IOT_PARTITION: !Ref 'AWS::Partition'
          IOT_REGION: !Ref 'AWS::Region'
          IOT_ACCOUNT_ID: !Ref 'AWS::AccountId'
      Code:
        ZipFile: |
          const https = require('https');
          const { IoTClient, CreatePolicyCommand, CreatePolicyVersionCommand,
            DeletePolicyCommand, DeletePolicyVersionCommand,
            ListPolicyVersionsCommand } = require('@aws-sdk/client-iot');

          const iot = new IoTClient({});
          const E = process.env;

          function send(event, context, status, data, pid, reason) {
            const body = JSON.stringify({
              Status: status,
              Reason: reason || ('See CloudWatch log stream ' + context.logStreamName),
              PhysicalResourceId: pid || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              NoEcho: false,
              Data: data || {}
            });
            const u = new URL(event.ResponseURL);
            return new Promise((resolve) => {
              const req = https.request({
                hostname: u.hostname, port: 443,
                path: u.pathname + u.search, method: 'PUT',
                headers: { 'content-type': '', 'content-length': Buffer.byteLength(body) }
              }, (res) => { res.resume(); res.on('end', resolve); });
              req.on('error', (e) => { console.error('send failed', e); resolve(); });
              req.write(body);
              req.end();
            });
          }

          function policyDocument() {
            const t = '${iot:Connection.Thing.ThingName}';
            const b = 'arn:' + E.IOT_PARTITION + ':iot:' + E.IOT_REGION + ':' + E.IOT_ACCOUNT_ID + ':';
            return JSON.stringify({
              Version: '2012-10-17',
              Statement: [
                { Sid: 'ConnectAsOwnThing', Effect: 'Allow', Action: 'iot:Connect',
                  Resource: b + 'client/' + t },
                { Sid: 'PublishOwnTopics', Effect: 'Allow', Action: 'iot:Publish',
                  Resource: [b + 'topic/devices/' + t + '/*',
                             b + 'topic/$aws/things/' + t + '/shadow/*'] },
                { Sid: 'SubscribeOwnTopics', Effect: 'Allow', Action: 'iot:Subscribe',
                  Resource: [b + 'topicfilter/devices/' + t + '/*',
                             b + 'topicfilter/$aws/things/' + t + '/shadow/*'] },
                { Sid: 'ReceiveOwnTopics', Effect: 'Allow', Action: 'iot:Receive',
                  Resource: [b + 'topic/devices/' + t + '/*',
                             b + 'topic/$aws/things/' + t + '/shadow/*'] }
              ]
            });
          }

          const suffix = (id) => String(id || '').replace(/[^a-zA-Z0-9]/g, '').slice(0, 8).toLowerCase();
          const build = (prefix, reqId) => prefix + '-' + E.STACK_NAME + '-' + suffix(reqId);
          const owned = (name) => typeof name === 'string' &&
            name.startsWith(E.POLICY_NAME_PREFIX + '-') === false ? false : true;

          async function createPolicy(name) {
            await iot.send(new CreatePolicyCommand({
              policyName: name, policyDocument: policyDocument()
            }));
          }

          async function pruneVersions(name, keepDefault) {
            const out = await iot.send(new ListPolicyVersionsCommand({ policyName: name }));
            const versions = out.policyVersions || [];
            for (const v of versions) {
              if (v.isDefaultVersion && keepDefault) continue;
              if (v.isDefaultVersion && !keepDefault) continue;
              await iot.send(new DeletePolicyVersionCommand({
                policyName: name, policyVersionId: v.versionId
              }));
            }
          }

          async function deletePolicy(name) {
            try {
              await pruneVersions(name, false);
              await iot.send(new DeletePolicyCommand({ policyName: name }));
            } catch (err) {
              if (err.name === 'ResourceNotFoundException') return;
              throw err;
            }
          }

          exports.handler = async (event, context) => {
            console.log('event', JSON.stringify(event));
            const props = event.ResourceProperties || {};
            const oldProps = event.OldResourceProperties || {};
            const prefix = props.PolicyNamePrefix || E.POLICY_NAME_PREFIX;
            let pid = event.PhysicalResourceId;
            try {
              if (event.RequestType === 'Create') {
                const name = build(prefix, event.RequestId);
                await createPolicy(name);
                return await send(event, context, 'SUCCESS', { PolicyName: name }, name);
              }
              if (event.RequestType === 'Update') {
                const prevPrefix = oldProps.PolicyNamePrefix || E.POLICY_NAME_PREFIX;
                if (prevPrefix !== prefix || !owned(pid)) {
                  const name = build(prefix, event.RequestId);
                  await createPolicy(name);
                  return await send(event, context, 'SUCCESS', { PolicyName: name }, name);
                }
                await pruneVersions(pid, true);
                await iot.send(new CreatePolicyVersionCommand({
                  policyName: pid, policyDocument: policyDocument(), setAsDefault: true
                }));
                return await send(event, context, 'SUCCESS', { PolicyName: pid }, pid);
              }
              if (event.RequestType === 'Delete') {
                if (owned(pid) && pid !== context.logStreamName) await deletePolicy(pid);
                return await send(event, context, 'SUCCESS', { PolicyName: pid }, pid);
              }
              return await send(event, context, 'FAILED', {}, pid,
                'Unsupported RequestType ' + event.RequestType);
            } catch (err) {
              console.error('handler failed', err);
              return await send(event, context, 'FAILED', {}, pid,
                (err && err.message) ? err.message : String(err));
            }
          };
      Tags:
        - Key: Environment
          Value: !Ref EnvironmentTag
        - Key: ManagedBy
          Value: !Ref 'AWS::StackName'

  IoTDevicePolicy:
    Type: Custom::IoTDevicePolicy
    DependsOn: OnboardingPolicyFunctionLogGroup
    Properties:
      ServiceToken: !GetAtt OnboardingPolicyFunction.Arn
      PolicyNamePrefix: !Ref PolicyNamePrefix
      EnvironmentTag: !Ref EnvironmentTag

Outputs:

  IoTDevicePolicyName:
    Description: Name of the generated IoT Core device-onboarding policy, scoped to each device's own thing name.
    Value: !GetAtt IoTDevicePolicy.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-IoTDevicePolicyName'

  OnboardingPolicyFunctionArn:
    Description: ARN of the Lambda function backing the IoT device-onboarding policy custom resource.
    Value: !GetAtt OnboardingPolicyFunction.Arn
    Export:
      Name: !Sub '${AWS::StackName}-OnboardingPolicyFunctionArn'

AWSTemplateFormatVersion: '2010-09-09'
Description: Creates a Cedar-based Amazon Verified Permissions policy store for a bookstore application, with strict schema validation, static access policies, and an SSM parameter publishing the policy store ID.

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Bookstore application Cedar policy store
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsmember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: !Sub '/${AWS::StackName}/bookstore/policy-store-id'
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId
      Description: Amazon Verified Permissions policy store ID for the bookstore application

  AdminViewAllBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidSpecificAdminViewPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid the specific administrator Dante from viewing books, overriding the admin permit
          Statement: |
            forbid (
              principal == Bookstore::User::"Dante",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only the books they own
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when { resource.owner == principal };

  SpecificUserSpecificBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit the specific user Alice to view one specific book
          Statement: |
            permit (
              principal == Bookstore::User::"Alice",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"978-0-3064-0615-7"
            );

  CustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Permit customers with two or more years of membership to view premium offers
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when { principal has yearsmember && principal.yearsmember >= 2 };

  ForbidNewCustomerPremiumOffersPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid customers with less than two years of membership from viewing premium offers
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            unless { principal has yearsmember && principal.yearsmember >= 2 };

  ForbidNonUSRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Description: Forbid View and ViewWithPremiumOffers whenever the request region is not the United States
          Statement: |
            forbid (
              principal,
              action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
              resource
            )
            when { context.region != "US" };

Outputs:
  PolicyStoreId:
    Description: ID of the bookstore Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.PolicyStoreId
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreId'
  PolicyStoreArn:
    Description: ARN of the bookstore Verified Permissions policy store
    Value: !GetAtt BookstorePolicyStore.Arn
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreArn'
  PolicyStoreIdParameterName:
    Description: Name of the SSM parameter holding the policy store ID
    Value: !Ref PolicyStoreIdParameter
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreIdParameterName'

AWSTemplateFormatVersion: '2010-09-09'
Description: Self-contained AWS AppSync GraphQL Todo API (TodoAPIwithJs) using API key authentication, JavaScript pipeline resolvers, and a DynamoDB table with an owner global secondary index, plus real-time subscriptions for create, update and delete events.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: owner-index
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to access the Todo DynamoDB table and its owner index.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: TodoTableAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/*'
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  AppSyncLoggingRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows AppSync to push logs to CloudWatch Logs.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncLoggingRole.Arn
        FieldLogLevel: ERROR
        ExcludeVerboseContent: true
      Tags:
        - Key: Application
          Value: TodoAPIwithJs
        - Key: Environment
          Value: dev

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          completed: Boolean
          createdAt: AWSDateTime
          updatedAt: AWSDateTime
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          owner: String!
          title: String!
          description: String
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          title: String
          description: String
          completed: Boolean
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          queryTodosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo: Todo @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo @aws_subscribe(mutations: ["deleteTodo"])
        }

  TodoTableDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: CreateTodoFunction
      Description: Creates a Todo item with DynamoDB PutItem
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          const item = {
            owner: input.owner,
            title: input.title,
            completed: input.completed === undefined || input.completed === null ? false : input.completed,
            createdAt: now,
            updatedAt: now,
          };
          if (input.description !== undefined && input.description !== null) {
            item.description = input.description;
          }
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
            condition: { expression: 'attribute_not_exists(id)' },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: GetTodoFunction
      Description: Retrieves a Todo item with DynamoDB GetItem
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: UpdateTodoFunction
      Description: Updates an existing Todo item with DynamoDB UpdateItem
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const values = { updatedAt: util.time.nowISO8601() };
          for (const [key, value] of Object.entries(input)) {
            if (key !== 'id' && value !== undefined && value !== null) {
              values[key] = value;
            }
          }
          const expressionNames = {};
          const expressionValues = {};
          const setClauses = [];
          for (const [key, value] of Object.entries(values)) {
            expressionNames[`#${key}`] = key;
            expressionValues[`:${key}`] = value;
            setClauses.push(`#${key} = :${key}`);
          }
          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: input.id }),
            update: {
              expression: `SET ${setClauses.join(', ')}`,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
            condition: { expression: 'attribute_exists(id)' },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: DeleteTodoFunction
      Description: Deletes a Todo item with DynamoDB DeleteItem and returns the deleted item
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
            condition: { expression: 'attribute_exists(id)' },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: ListTodosFunction
      Description: Lists Todo items with a paginated DynamoDB Scan
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Scan',
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  QueryTodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: QueryTodosByOwnerFunction
      Description: Queries Todo items by owner using the owner-index GSI
      DataSourceName: !GetAtt TodoTableDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const request = {
            operation: 'Query',
            index: 'owner-index',
            query: {
              expression: '#owner = :owner',
              expressionNames: { '#owner': 'owner' },
              expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.args.owner }),
            },
            limit: ctx.args.limit ? ctx.args.limit : 20,
          };
          if (ctx.args.nextToken) {
            request.nextToken = ctx.args.nextToken;
          }
          return request;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

